    public void relaxed_RelaxedTagsAndAttributesAreAllowed() {
        Safelist safelist = Safelist.relaxed();
        assertTrue(safelist.isSafeAttribute("script", null, null));
        assertTrue(safelist.isSafeTag("noscript"));
